import React, { createContext, useContext, useState, useEffect } from 'react';

export type Partition = 'marketing' | 'app' | 'staff' | 'admin';

export interface PartitionContextType {
  activePartition: Partition;
  setActivePartition: (partition: Partition) => void;
  getPortalUrl: (partition: Partition) => string;
  isRoleAllowed: (role?: string) => boolean;
  requiredPartitionForRole: (role?: string) => Partition;
}

const PartitionContext = createContext<PartitionContextType | undefined>(undefined);

export function detectPartitionFromLocation(): Partition {
  if (typeof window === 'undefined') return 'marketing';

  // Allow override via query param ?portal=app|staff|admin|marketing
  const params = new URLSearchParams(window.location.search);
  const portalParam = params.get('portal')?.toLowerCase() as Partition | null;
  if (portalParam && ['marketing', 'app', 'staff', 'admin'].includes(portalParam)) {
    return portalParam;
  }

  const hostname = window.location.hostname.toLowerCase();
  if (hostname.startsWith('admin.')) return 'admin';
  if (hostname.startsWith('staff.')) return 'staff';
  if (hostname.startsWith('app.')) return 'app';

  return 'marketing';
}

export function requiredPartitionForRole(role?: string): Partition {
  if (!role) return 'app';
  const norm = role.toLowerCase().replace(/[\s_-]+/g, '');
  if (norm.includes('admin') || norm.includes('superuser')) return 'admin';
  if (
    norm.includes('agent') ||
    norm.includes('lawyer') ||
    norm.includes('advocate') ||
    norm.includes('surveyor') ||
    norm.includes('official') ||
    norm.includes('staff')
  ) {
    return 'staff';
  }
  return 'app';
}

export function isRoleAllowedOnPartition(role: string | undefined, partition: Partition): boolean {
  if (!role) return true; // Public access
  const req = requiredPartitionForRole(role);
  if (partition === 'marketing') return true;
  return req === partition;
}

export function getPortalUrl(partition: Partition): string {
  if (typeof window === 'undefined') return '/';
  const host = window.location.hostname.toLowerCase();
  const protocol = window.location.protocol;
  const port = window.location.port ? `:${window.location.port}` : '';

  // Local development override
  if (host === 'localhost' || host === '127.0.0.1') {
    return `${protocol}//${host}${port}?portal=${partition}`;
  }

  // Production subdomain partitions
  switch (partition) {
    case 'app':
      return 'https://app.digiland.co.ke';
    case 'staff':
      return 'https://staff.digiland.co.ke';
    case 'admin':
      return 'https://admin.digiland.co.ke';
    case 'marketing':
    default:
      return 'https://www.digiland.co.ke';
  }
}

export const PartitionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [activePartition, setActivePartition] = useState<Partition>(detectPartitionFromLocation);

  useEffect(() => {
    const detected = detectPartitionFromLocation();
    setActivePartition(detected);
  }, []);

  const isRoleAllowed = (role?: string) => isRoleAllowedOnPartition(role, activePartition);

  return (
    <PartitionContext.Provider
      value={{
        activePartition,
        setActivePartition,
        getPortalUrl,
        isRoleAllowed,
        requiredPartitionForRole,
      }}
    >
      {children}
    </PartitionContext.Provider>
  );
};

export function usePartition() {
  const context = useContext(PartitionContext);
  if (!context) {
    throw new Error('usePartition must be used within a PartitionProvider');
  }
  return context;
}
